using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "KarmicOrbStarAbility", menuName = "Data/Battle/Effects/Orion/KarmicOrb Star Ability")]
public class KarmicOrbStarAbility : ActivateStarAbility
{
	[Header("Debt Star Enhancer")]
	[SerializeField]
	[HideIf("evilConstellation")]
	private CrystallizedMemoryOmenData crystallizedMemoryOmenData;

	public override string GetLocalizedDescription()
	{
		return GetLocalizedDescriptionWithCastOrb(GetLocalizedDescriptionWithModifications());
	}

	private string GetLocalizedDescriptionWithModifications()
	{
		if (evilConstellation)
		{
			return battleAction.GetActionDescription(actionValue);
		}
		if (GameScenesUtils.IsBattleScene() && ReferenceSingleton<OrionOmensHandler>.Instance.CrystallizedMemoryOmenActive)
		{
			return crystallizedMemoryOmenData.PurifyWithBadEffectAction.GetActionDescription(crystallizedMemoryOmenData.PurifyAmount);
		}
		return battleAction.GetActionDescription(actionValue);
	}

	protected override int GetModifiedActionValue()
	{
		if (evilConstellation)
		{
			return actionValue;
		}
		if (!ReferenceSingleton<OrionOmensHandler>.Instance.CrystallizedMemoryOmenActive)
		{
			return actionValue;
		}
		return crystallizedMemoryOmenData.PurifyAmount;
	}

	protected override BattleAction GetBattleAction()
	{
		if (evilConstellation)
		{
			return battleAction;
		}
		if (ReferenceSingleton<OrionOmensHandler>.Instance.CrystallizedMemoryOmenActive)
		{
			return crystallizedMemoryOmenData.PurifyWithBadEffectAction;
		}
		return battleAction;
	}

	public override void OnActivateStarAbility()
	{
		if (!evilConstellation)
		{
			ReferenceSingleton<OrionOmensHandler>.Instance.OnActivateMirrorOfThoughtOmen();
		}
		base.OnActivateStarAbility();
	}

	public override void OnExitingStar()
	{
		if (!evilConstellation)
		{
			ReferenceSingleton<OrionOmensHandler>.Instance.OnDeactivatingKarmicOrbActivateMirrorOfThoughtOmen();
		}
	}
}
